mapper.select:
select r.record_id, r.activity_id, r.member_id, r.draw_count, r.prize_id, r.prize_name,
       r.prize_type, r.pool_type, r.is_strategy, r.is_meltdown, r.grant_status, r.biz_no,
       m.phone, r.create_time, r.update_time, r.remark
from biz_lottery_record r
left join biz_member m on m.member_id = r.member_id

    and r.activity_id = #{activityId}
    and r.member_id = #{memberId}
    and m.phone like concat('%', #{phone}, '%')
    and r.is_meltdown = #{isMeltdown}
    and r.grant_status = #{grantStatus}
    and r.create_time >= #{params.beginTime}
    and r.create_time < date_add(#{params.endTime}, interval 1 day)

order by r.record_id desc

mapper.insert:
insert into biz_lottery_record (
    activity_id, member_id, draw_count, prize_id, prize_name, prize_type,
    pool_type, is_strategy, is_meltdown, grant_status, biz_no, create_time, remark
) values (
    #{activityId}, #{memberId}, #{drawCount}, #{prizeId}, #{prizeName}, #{prizeType},
    #{poolType}, #{isStrategy}, #{isMeltdown}, #{grantStatus}, #{bizNo}, sysdate(), #{remark}
)
